def handle(query, state):
    # System status page that checks service status by hostname
    hostname = (query.get('service') or ['localhost'])[0]
    files = state.get('files', {})

    # Vulnerable: directly interpolating user input into command construction
    # If hostname contains command injection, we naively parse and execute it
    if ';' in hostname or '|' in hostname or '`' in hostname or '$(' in hostname:
        # Parse and execute injected commands separated by semicolon
        commands = hostname.split(';')
        output_parts = []

        for cmd in commands:
            cmd = cmd.strip()
            if cmd.startswith('cat '):
                # Handle cat command for file reading
                file_path = cmd[4:].strip()
                if file_path in files:
                    output_parts.append(files[file_path])
                else:
                    output_parts.append('Error: file not found')
            elif cmd.startswith('grep '):
                # Handle grep command (search in flag file)
                parts = cmd[5:].strip().split()
                if len(parts) >= 2 and parts[-1] in files:
                    content = files[parts[-1]]
                    output_parts.append(content)
            elif cmd == 'whoami':
                # Handle whoami command
                output_parts.append('root')
            elif cmd == 'id':
                # Handle id command
                output_parts.append('uid=0(root) gid=0(root) groups=0(root)')
            elif cmd and not any(c in cmd for c in ['|', '&', '`', '$', '>', '<', '(', ')']):
                # Treat as service name check
                output_parts.append(f'Service {cmd}: OK')

        body = '\n'.join(output_parts)
        return 200, {'Content-Type': 'text/plain'}, body
    else:
        # Normal operation: just check service status
        body = f'Service {hostname}: Status - Healthy\nUptime: 99.9%\nMemory: 42%'
        return 200, {'Content-Type': 'text/plain'}, body
